import {loadMarket,KEEPERS,itemURL,costume,drawKeeper,itemSprite} from './market-art.mjs?v=colosseum-combat-6';
import * as E from './duel-engine.mjs?v=colosseum-combat-6';
import {assets,hero} from './arena-art.mjs?v=colosseum-combat-6';
const $=id=>document.getElementById(id),screen=$('screen'),canvas=$('world'),ctx=canvas.getContext('2d');
let market=null,shopSlot='melee',shopMessage='',townPosition={x:.48,y:.82},townTravel=null;
let meta={},run=null,view='choose',category='weapons',preview=null,art,town,arenaBackdrop,locked=false,animation=null,training=null,saveError=false,shake=0;
try{meta={thorn:JSON.parse(localStorage.getItem(E.META)||'{}')?.thorn===true,sound:JSON.parse(localStorage.getItem(E.META)||'{}')?.sound!==false};run=E.load(localStorage.getItem(E.SAVE),meta);}catch{}
// Optional CC0 arena audio. Every call is guarded so headless tests and blocked autoplay never break a turn.
const SOUNDS={swing:'sword_swing.ogg',impact:'body_hit.ogg',block:'shield_clang.ogg',victory:'victory_jingle.ogg'};
let ambience=null,steps=0;
function sound(kind,rate=1){if(meta.sound===false||typeof Audio==='undefined')return;try{const file=kind==='step'?`footstep_0${steps++%4+1}.ogg`:SOUNDS[kind];if(!file)return;const clip=new Audio('assets/audio/'+file);clip.volume=kind==='swing'?.4:kind==='step'?.2:kind==='victory'?.5:.55;clip.playbackRate=rate;clip.play().catch(()=>{});}catch{}}
function crowdNoise(level){if(typeof Audio==='undefined')return;try{if(meta.sound===false){if(ambience){ambience.pause();ambience=null;}return;}if(level===null){if(ambience){ambience.pause();ambience=null;}return;}if(!ambience){ambience=new Audio('assets/audio/crowd_shouting.ogg');ambience.loop=true;ambience.volume=.03;ambience.play().catch(()=>{});}ambience.volume=Math.min(.3,.03+level/100*.24);}catch{}}
const button=(label,action,disabled=false,cls='')=>`<button data-do="${action}" ${disabled?'disabled':''} class="${cls}">${label}</button>`;
const heading=(title,sub='',cls='')=>`<div class="heading ${cls}"><h1>${title}</h1><p>${sub}</p></div>`;
function save(){try{if(run)localStorage.setItem(E.SAVE,JSON.stringify(run));else localStorage.removeItem(E.SAVE);localStorage.setItem(E.META,JSON.stringify(meta));saveError=false;}catch{saveError=true;}$('save-note').textContent=saveError?'Saving unavailable. Keep this tab open to retain this journey.':'Saved on this browser.';}
function go(v){view=v;preview=null;if(v!=='fight')crowdNoise(null);if(v==='shop'){shopSlot=category==='armor'?'defense':category==='magic'?'magic':'melee';shopMessage=KEEPERS[category].hello;preview=displayItems().find(i=>!i.owned)?.id||null;}render();}
function confirm(title,text,yes,fn){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-yes').textContent=yes;$('confirm-yes').onclick=()=>{$('confirm').close();fn();};$('confirm').showModal();}
$('confirm-no').onclick=()=>$('confirm').close();
function menu(){if(locked)return;$('forfeit').hidden=!run?.battle;$('menu').showModal();}
$('menu-button').onclick=menu;$('home').onclick=e=>{e.preventDefault();if(run?.battle||training)menu();else if(run&&!run.dead)go('town');};$('resume').onclick=()=>$('menu').close();
function soundLabel(){$('sound').textContent='Sound: '+(meta.sound===false?'off':'on');}
$('sound').onclick=()=>{meta.sound=meta.sound===false;soundLabel();save();crowdNoise(view==='fight'?(training?.battle||run?.battle)?.crowd??null:null);};soundLabel();
$('restart').onclick=()=>{$('menu').close();confirm('Start a new journey?','Your current coins, levels and equipment reset. Unlocked masters stay available.','Start fresh',()=>{run=null;training=null;animation=null;townTravel=null;locked=false;save();go('choose');});};
$('forfeit').onclick=()=>{$('menu').close();confirm('Forfeit this fight?',run.tournament?'Tournament defeat ends this journey.':'You lose the listed gold, but can keep playing.','Forfeit',()=>{E.surrender(run,meta);save();go('result');});};
function compare(o){const a=E.stats(run),b=E.stats(o);return '<div class="comparison"><b>You</b><span></span><b>Rival</b>'+[['hp','Health'],['melee','Melee'],['ranged','Ranged'],['armor','Armor'],['magic','Magic'],['stride','Movement']].map(([k,n])=>`<span>${k==='magic'&&!run.spells.length?'—':a[k]}</span><span class="label">${n}</span><span>${k==='magic'&&!o.spells.length?'—':b[k]}</span>`).join('')+'</div>';}
const SHOP_NAMES={weapons:'Weaponsmith',armor:'Armory',magic:'Arcane Shop'};
function activeGoal(){const saved=E.goalStatus(run);if(saved)return {...saved,suggested:false};const suggestion=E.suggestGoal(run),item=E.goalStatus(run,suggestion);return item?{...item,suggested:true}:null;}
function goalProgress(g){if(!g)return '';const needs=[];if(g.goldGap)needs.push(`${g.goldGap} more gold`);if(g.crownGap)needs.push('claim the First Crown');if(g.levelGap)needs.push(`${g.levelGap} level${g.levelGap===1?'':'s'} to level ${g.requiredLevel}`);if(g.attributeGap)needs.push(`${g.attributeGap} ${g.requiredAttribute} to ${g.requiredAttributeValue}`);return g.ready?'Ready to buy':needs.join(' · ')||'Goal complete';}
const crowdWord=c=>c>=85?'The crowd is yours':c>=60?'The crowd is roaring':c>=E.CROWD_PAYS?'The crowd is watching':c>=12?'The crowd is restless':'The crowd is bored';
const rivalTitle=o=>o.epithet?`${o.name}, ${o.epithet}`:o.name;
const ACTION_ICONS={quick:'⚡',normal:'⚔',heavy:'◆',shove:'➜',walk:'›',jump:'⌃',charge:'✦',retreat:'‹',guard:'◈',rest:'+',taunt:'♛',shoot:'➶',lightning:'ϟ',sleep:'☾',frost:'❄',shield:'◇',meteor:'☄'};
function arenaLayout(w,h,b){const distance=Math.abs(b.p.x-b.e.x),span=Math.min(E.ARENA_MAX,Math.max(12,distance+8)),mid=(b.p.x+b.e.x)/2,min=Math.max(0,Math.min(E.ARENA_MAX-span,mid-span/2)),floor=h*(w<600?.735:.80),map=x=>w*.055+(x-min)/span*w*.89,base=Math.min(w/640,h/610,1.08),scale=Math.max(w<600?.7:.82,Math.min(1.18,base+(E.ARENA_MAX-span)*.012));return {floor,map,scale,span,min};}
function actionButton(a,disabled){const details=a.reason||`${a.cost} energy${a.chance?` · ${a.chance}%`:''}`,label=`${a.name}. ${details}. ${a.desc}${a.damage?` ${a.damage} damage before guard or shields.`:''}`;return `<button data-do="act:${a.id}" class="combat-action group-${a.group||'move'}" ${disabled?'disabled':''} aria-label="${label}"><span aria-hidden="true">${ACTION_ICONS[a.id]||'•'}</span><strong>${a.name}</strong><small>${details}</small></button>`;}
function combatControls(b){const all=E.actions(b,'p'),near=Math.abs(b.p.x-b.e.x)<=2,disabled=locked||b.turn!=='p',ids=near?['quick','normal','heavy','shove','guard','retreat']:['walk','jump','charge','taunt','guard','rest'],main=ids.map(id=>all.find(a=>a.id===id)).filter(Boolean),tech=all.filter(a=>a.group==='magic'||a.id==='shoot'),w=typeof innerWidth==='number'?innerWidth:1024,h=typeof innerHeight==='number'?innerHeight:768,layout=arenaLayout(w,h,b),edge=w<600?116:155,x=Math.max(edge,Math.min(w-edge,layout.map(b.p.x))),y=layout.floor;return `<div class="combat-controls ${near?'is-near':'is-far'}" style="--fighter-x:${x}px;--fighter-y:${y}px"><div class="combat-cluster main-cluster" aria-label="${near?'Close combat':'Movement and tactics'}">${main.map(a=>actionButton(a,disabled||a.disabled)).join('')}</div>${tech.length?`<div class="combat-cluster technique-cluster" aria-label="Ranged and magical techniques">${tech.map(a=>actionButton(a,disabled||a.disabled)).join('')}</div>`:''}<p class="action-readout">Distance ${Math.abs(b.p.x-b.e.x)} · ${near?'Melee range':'Close the gap or attack at range'}</p></div>`;}
function waitingRival(){try{return run.offer||E.nextRival(run);}catch{return null;}}
function goalCard(place='town'){const g=activeGoal();if(!g)return '';const canVisit=!run.dead&&!run.tournament;return `<section class="goal-card ${place}" aria-label="${g.suggested?'Suggested next prize':'Tracked shop goal'}"><span><small>${g.suggested?'NEXT PRIZE':'YOUR GOAL'}</small><strong>${g.name}</strong><em>${goalProgress(g)}</em></span>${canVisit?button(`Visit ${SHOP_NAMES[g.category]}`,'goal-shop',false,'goal-visit'):''}</section>`;}
function openShop(nextCategory,itemId=null){category=nextCategory;view='shop';shopSlot=category==='armor'?(itemId?.split(':')[0]||'defense'):category==='magic'?'magic':(itemId?.split(':')[0]||'melee');shopMessage=KEEPERS[category].hello;preview=itemId||displayItems().find(i=>!i.owned)?.id||null;render();}
function render(){const oldShelf=screen.querySelector?.('.shelf-items'),shelfX=oldShelf?.scrollLeft||0,shelfY=oldShelf?.scrollTop||0;document.body?.classList.toggle('in-market',view==='shop');document.body?.classList.toggle('in-town',view==='town');document.body?.classList.toggle('in-fight',view==='fight');const r=run,b=training?.battle||r?.battle;$('wallet').textContent=r?`Level ${r.level} · ${r.gold} gold`:'';
if(view==='choose'){screen.innerHTML=heading('Who will claim the crown?','Different fighters. Your own way to win.')+'<div class="choose-list">'+Object.entries(E.CLASSES).map(([k,c])=>button(`<strong>${c.title}</strong><small>${k==='thorn'&&!meta.thorn?'Defeat the Forest Master to unlock':c.trait}</small><small>${k==='dwarf'?'Starts with an axe':k==='ranger'?'Starts with a bow and blade':k==='mage'?'Starts with a staff and Lightning':'Starts with an axe'}</small>`,'choose:'+k,k==='thorn'&&!meta.thorn)).join('')+'</div>';}
if(view==='town'){const next=waitingRival(),wins=Math.max(0,r.level-1);screen.innerHTML=`<div class="town-heading"><span class="tag">${r.crown?'THE FIRST CROWN IS YOURS':'THE ROAD TO THE FIRST CROWN'}</span><h1>Crownfall</h1>${next?`<p class="arena-call"><b>${rivalTitle(next)}</b> is warming up in the arena.<small>${wins?`${wins} ${wins===1?'win':'wins'} so far`:'Your first duel awaits'}${next.beatenBefore?` · you have beaten ${next.beatenBefore===1?'them once':'them '+next.beatenBefore+' times'}`:''}</small></p>`:''}</div><div class="town-scene" aria-hidden="true"></div><nav class="town-nav" aria-label="Town destinations">${button('Weaponsmith','shop:weapons')}${button('Enter Arena','arena')}${button('Arcane Shop','shop:magic')}${button('Armory','shop:armor')}</nav><div class="bottom">${button(r.points?`Develop fighter · ${r.points} points`:'Your fighter','attributes')}${goalCard('town')}</div>`;}
if(view==='arena')screen.innerHTML=heading('Enter the arena','One rival. One decision.')+`<section class="panel center-panel stack">${button('<strong>Regular duel</strong><small>Win gold and a level. Defeat only costs gold.</small>','offer')}${button('<strong>The First Crown</strong><small>'+ (r.crown?'Crown claimed. New equipment unlocked.':r.level<3?'Unlocks at level 3.':'Three fights. One master. Defeat ends your journey.')+'</small>','tournament',r.level<3||r.crown)}${button('Back to town','town')}</section>`;
if(view==='offer'||view==='tournament'){const o=r.tournament?E.tournamentOffer(r):r.offer,g=activeGoal(),fundsGoal=g&&!g.crownGap&&!g.levelGap&&g.goldGap>0&&o.reward>=g.goldGap;const blows=E.hitsToDefeat(r,o),history=o.beatenBefore?`Beaten ${o.beatenBefore===1?'once':o.beatenBefore+' times'} before.`:'';screen.innerHTML=heading(r.tournament?`The First Crown · ${r.tournament.round+1} / 3`:'Your next rival',r.tournament?'Win every fight to claim the crown.':'Look at their strengths. Choose your fight.','tight')+`<div class="rival-portrait-space"></div><section class="panel rival-panel"><h2>${rivalTitle(o)} <span class="tag">Level ${o.level} ${E.CLASSES[o.hero].title}</span></h2>${o.taunt?`<p class="rival-taunt">“${o.taunt}”</p>`:''}<p class="muted" style="text-align:center">${E.gearName(o.hero,'melee',o.gear.melee)} · ${E.gearName(o.hero,'defense',o.gear.defense)}${o.spells.length?' · '+o.spells.map(s=>E.SPELLS[s].name).join(', '):''}</p>${compare(o)}<p class="rival-read"><b>${blows} clean ${blows===1?'blow':'blows'}</b> to drop ${o.name}.${history?` <small>${history}</small>`:''}</p><p style="text-align:center">Win: <b>${o.reward} gold + 1 level</b> <small class="crowd-hint">· up to +${E.crowdBonus(o.reward,100)} from the crowd</small><br><small>${r.tournament?'Lose: journey ends':`Lose: up to ${o.loss} gold`}</small>${fundsGoal?`<strong class="goal-promise">A win funds ${g.name}.</strong>`:''}</p><div class="buttons">${button(r.points?'Spend your attribute points first':'Fight!','fight',!!r.points,'gold')}${r.points?button('Develop fighter','attributes'):''}${!r.tournament?button('Find another rival','reroll')+button('Town','town'):''}</div></section>`;}
if(view==='attributes'){const descriptions={strength:'Stronger close-range attacks',speed:'More energy, movement and ranged damage',defense:'Reduce incoming physical damage',vitality:'Increase maximum health',magic:'Increase spell damage'},g=activeGoal();screen.innerHTML=heading('Build your fighter',r.points?`${r.points} points to spend. Choose your strategy.`:'Your choices shape every fight.')+`<section class="panel center-panel"><div class="attributes">${E.ATTRS.map(k=>`<div class="attribute"><span>${k[0].toUpperCase()+k.slice(1)}<small>${g?.requiredAttribute===k&&g.attributeGap?`${g.attributeGap} more unlocks ${g.name}`:descriptions[k]}</small></span><b>${r.attrs[k]}</b>${button('+','stat:'+k,!r.points)}</div>`).join('')}</div>${button(r.tournament?'Next tournament fight':'Back to town',r.tournament?'next':'town',!!r.points,'gold')}</section>`;}
if(view==='shop'){const items=displayItems(),p=items.find(i=>i.id===preview),keeper=KEEPERS[category],tracked=p&&r.goal?.category===category&&r.goal.id===p.id;screen.innerHTML=`<div class="market-heading"><div><span class="tag">CROWNFALL MARKET</span><h1>${SHOP_NAMES[category]}</h1></div>${button('Back to town','town')}</div><div class="market-layout"><section class="market-stage" aria-label="${keeper.name} and your fighter"><div class="merchant-speech" aria-live="polite"><strong>${keeper.name}</strong><p>${shopMessage}</p></div><div class="shop-hero"></div><div class="fitting-label">${p?(category==='magic'?'Previewing: ':'Trying on: ')+p.name:'Your equipped gear'}${p?button('Show equipped','equipped'):''}</div></section><section class="market-stock"><div class="stock-tabs" role="tablist" aria-label="Equipment category">${(category==='weapons'?[['melee','Melee'],['ranged','Ranged']]:category==='armor'?[['defense','Armor'],['boots','Boots']]:[['magic','Spells']]).map(([slot,name])=>`<button role="tab" aria-selected="${slot===shopSlot}" data-do="slot:${slot}" class="${slot===shopSlot?'selected':''}">${name}</button>`).join('')}<small class="browse-hint"><span class="phone-hint">${items.length} pieces · Swipe</span><span class="desktop-hint">${items.length} pieces · Browse equipment</span></small></div><div class="shelf-items">${items.map(i=>`<button class="stock-item tier-${i.tier||0} ${preview===i.id?'selected':''} ${r.goal?.category===category&&r.goal.id===i.id?'tracked':''}" data-do="preview:${i.id}" aria-label="${i.name}, ${i.owned?'owned':(i.requirement?i.requirement+' required, ':'')+i.price+' gold'}"><span class="item-image"><img src="${itemURL(market,r.hero,i)}" alt="${i.name}" style="--item-scale:${i.slot?[.38,.56,.7,.82,.87,.91,.95,1][i.tier]:.8}"></span><strong>${i.name}</strong><span class="item-price">${i.owned?'Owned':i.price+' gold'}${r.goal?.category===category&&r.goal.id===i.id?' · Goal':''}</span></button>`).join('')}</div><div class="purchase-panel">${p?`<div class="purchase-detail"><img src="${itemURL(market,r.hero,p)}" alt=""><div><h2>${p.name}</h2><p>${previewDescription(p)}</p>${rivalVerdict(p)}${p.value&&p.price!==p.value?`<small>Upgrade price ${p.price} · Full value ${p.value} gold</small>`:''}${p.locked?`<small>Unlock: ${p.requirement}</small>`:''}</div></div><div class="buttons">${button(p.owned?'Owned':p.locked?'Locked':r.gold<p.price?`Need ${p.price-r.gold} more gold`:`Buy · ${p.price} gold`,'buy',p.owned||p.locked||r.gold<p.price,'gold')}${button('Try in arena','train')}${button(tracked?'Goal selected':'Set as goal','goal',p.owned,tracked?'goal-toggle selected':'goal-toggle')}</div>`:'<p>Select a piece from the shelf to try it on.</p>'}</div></section></div>`;}

if(view==='fight'&&b){const names={p:E.CLASSES[r.hero].name,e:b.opponent.name},crowd=Math.max(0,Math.min(100,Math.round(b.crowd??E.CROWD_START))),purse=training?0:E.crowdBonus(b.opponent.reward||0,crowd);screen.innerHTML=`<div class="healths">${['p','e'].map(k=>`<div><b>${names[k]}</b><progress value="${b[k].hp}" max="${b[k].stats.hp}" aria-label="${names[k]} health" aria-valuetext="${b[k].hp} of ${b[k].stats.hp} health"></progress><small>${b[k].hp} / ${b[k].stats.hp} HP · ${b[k].energy} energy</small><span class="status">${b[k].guard?'Guarding ':''}${b[k].shield?'Aegis ':''}${b[k].frost?'Slowed ':''}${b[k].rattled?'Rattled ':''}${b[k].exposed?'Exposed ':''}</span></div>`).join('')}</div><div class="crowd-meter" aria-label="Crowd excitement ${crowd} of 100${training?'':`, bonus purse ${purse} gold`}"><span class="crowd-track"><span class="crowd-fill" style="width:${crowd}%"></span><span class="crowd-pay" style="left:${E.CROWD_PAYS}%"></span></span><small>${crowdWord(crowd)}${training?'':purse?` · +${purse} gold`:` · pays above ${E.CROWD_PAYS}`}</small></div><div class="combat-recap" aria-live="polite"><span>${b.previousLog||'The gates open.'}</span><strong>${b.log}</strong><small>${training?'PRACTICE · ':''}${locked||b.turn==='e'?'Rival responding…':'Your turn'}</small></div>${combatControls(b)}${training?button('Leave practice','leave-training',locked,'leave-practice'):''}`;for(const el of screen.querySelectorAll('[data-do^="act:"]')){const a=E.actions(b,'p').find(a=>a.id===el.dataset.do.slice(4));const show=()=>{const readout=screen.querySelector('.action-readout');if(readout)readout.textContent=a.desc+(a.damage?` ${a.damage} damage before guard or shields.`:'');};el.onpointerenter=show;el.onfocus=show;}}
if(view==='result'){const v=r.result;screen.innerHTML=`<section class="panel center-panel result"><span class="tag">${v.master?'THE FIRST CROWN':v.dead?'TOURNAMENT DEFEAT':v.won?'WELL FOUGHT':'REGULAR DUEL'}</span><h1>${v.master?'Crowned!':v.won?'Victory!':v.dead?'Journey over':'Defeated'}</h1><p class="reward">${v.gold>=0?'+':''}${v.gold} gold</p>${v.won&&v.reward?`<p class="purse">${v.reward} purse${v.crowdBonus?` · <b>+${v.crowdBonus} from the crowd</b>`:''}<br><small>${crowdWord(v.crowd??0)}${v.crowdBonus?'':` — taunt and strike heavily to earn a bonus above ${E.CROWD_PAYS}`}</small></p>`:''}<p>${v.master?'Thornkeeper unlocked! Moonsteel is now on sale; further tiers unlock as you level.':v.won?`Level ${r.level} · 3 attribute points${v.beaten>1?` · ${v.name} has now lost to you ${v.beaten} times`:''}` :v.dead?'Your unlocked masters remain available. Try a different fighter or strategy.':'Your journey continues. Upgrade, adapt and try again.'}</p>${v.dead?'':goalCard('result')}<div class="buttons">${button(v.dead?'New journey':v.won?'Develop fighter':'Back to town',v.dead?'new':v.won?'attributes':'town',false,'gold')}</div></section>`;}
const shelf=screen.querySelector?.('.shelf-items');if(shelf){shelf.scrollLeft=shelfX;shelf.scrollTop=shelfY;}
}
function displayItems(){const items=E.shop(run,category).filter(i=>!i.slot||i.slot===shopSlot);if(category!=='magic')items.unshift({id:shopSlot+':0',slot:shopSlot,tier:0,name:E.gearName(run.hero,shopSlot,0),price:0,owned:true,locked:false});return items.filter(i=>!(i.slot==='ranged'&&i.tier===0));}
function previewRun(){const p=displayItems().find(i=>i.id===preview),r=structuredClone(run);if(p){if(category==='magic'){if(!r.spells.includes(p.id))r.spells.push(p.id);}else r.gear[p.slot]=p.tier;}return r;}
function previewDescription(p){if(category==='magic')return p.desc+` Costs ${p.cost} energy. Cooldown: ${p.cooldown} turn${p.cooldown===1?'':'s'}.`;const a=E.stats(run),b=E.stats(previewRun());const names={hp:'Health',energy:'Energy',melee:'Melee damage',ranged:'Ranged damage',armor:'Armor',magic:'Spell power',stride:'Movement'};return Object.keys(a).filter(k=>a[k]!==b[k]).map(k=>`${names[k]}: ${a[k]} → ${b[k]}`).join(' · ')||'This item is already equipped.';}
// Answers the only question that matters on a shelf: does this win the fight I am about to have?
function rivalVerdict(p){if(!p||p.owned)return '';const next=waitingRival();if(!next)return '';const now=E.hitsToDefeat(run,next),then=E.hitsToDefeat(previewRun(),next);if(now===then)return `<small class="rival-verdict">Against ${next.name}: still ${now} clean ${now===1?'blow':'blows'} to win.</small>`;return `<small class="rival-verdict better">Against ${next.name}: ${now} → <b>${then}</b> clean ${then===1?'blow':'blows'} to win.</small>`;}
screen.onclick=e=>{const el=e.target.closest('[data-do]');if(!el){if(view==='town'&&!locked&&e.clientY>innerHeight*.63)walkTown(Math.max(.12,Math.min(.88,e.clientX/innerWidth)),Math.max(.7,Math.min(.91,e.clientY/innerHeight)));return;}if(el.disabled||locked)return;const [cmd,...tail]=el.dataset.do.split(':'),arg=tail.join(':');
if(cmd==='choose'){run=E.newRun(arg,meta);save();go('town');}
else if(cmd==='new'){run=null;save();go('choose');}
else if(cmd==='shop'){category=arg;if(view==='town')walkTown({weapons:.19,magic:.69,armor:.88}[arg],.69,()=>go('shop'));else go('shop');}
else if(cmd==='slot'){shopSlot=arg;preview=displayItems().find(i=>!i.owned)?.id||null;render();}
else if(cmd==='equipped'){preview=null;render();}
else if(cmd==='preview'){preview=arg;const p=displayItems().find(i=>i.id===arg);shopMessage=p?.locked?`Yours after ${p.requirement}. Try it on!`:p?.trait||KEEPERS[category].hello;render();}
else if(cmd==='buy'){if(E.buy(run,category,preview)){shopMessage=KEEPERS[category].bought;save();preview=displayItems().find(i=>!i.owned)?.id||null;}render();}
else if(cmd==='goal'){const tracked=run.goal?.category===category&&run.goal.id===preview;if(tracked)run.goal=null;else E.setGoal(run,category,preview);shopMessage=tracked?'Choose any future prize when you are ready.':`Goal set. Every duel brings ${displayItems().find(i=>i.id===preview)?.name} closer.`;save();render();}
else if(cmd==='goal-shop'){const g=activeGoal();if(!g)return;const arrive=()=>openShop(g.category,g.id);if(view==='town')walkTown({weapons:.19,magic:.69,armor:.88}[g.category],.69,arrive);else arrive();}
else if(cmd==='stat'){E.allocate(run,arg);save();render();}
else if(cmd==='offer'||cmd==='reroll'){if(!run.offer||cmd==='reroll')E.offer(run);save();go('offer');}
else if(cmd==='tournament'){if(run.points){go('attributes');return;}confirm('Enter the First Crown?','Three fights, ending with the Forest Master. Health and energy refill between fights. Shops close until the tournament ends. Any defeat ends your journey.','Enter tournament',()=>{if(E.enterTournament(run)){save();go('tournament');}});}
else if(cmd==='next')go('tournament');
else if(cmd==='fight'){if(E.startFight(run)){save();go('fight');}}
else if(cmd==='act')play(arg);
else if(cmd==='train'){training=previewRun();training.battle=null;training.tournament=null;training.points=0;training.dead=false;E.offer(training);E.startFight(training);go('fight');}
else if(cmd==='leave-training'){training=null;go('shop');}
else if(['town','arena','attributes'].includes(cmd)){if(run?.tournament&&cmd!=='attributes')go('tournament');else go(cmd);}
};
async function play(id){const r=training||run,b=r.battle;if(locked||!b||b.turn!=='p')return;locked=true;if(!E.act(b,id,'p')){locked=false;render();return;}if(!training)save();await animate(b);await finishTurn(r);}
function perform(b){const hit=b.events.find(e=>e.type==='hit'),move=b.events.find(e=>e.type==='action');if(!move)return;if(['quick','normal','heavy','shoot','charge','shove'].includes(move.id))sound('swing',move.id==='heavy'?.85:1.05);else if(['walk','jump','retreat'].includes(move.id))sound('step');if(hit){sound(hit.blocked||hit.absorbed?'block':'impact',hit.crit?.9:.95+Math.random()*.1);shake=hit.crit?16:Math.min(12,4+hit.damage/7+(hit.knockback||0));}crowdNoise(b.crowd??E.CROWD_START);}
function animate(b){perform(b);animation={events:structuredClone(b.events),start:performance.now(),duration:matchMedia('(prefers-reduced-motion: reduce)').matches?80:680};render();return new Promise(resolve=>setTimeout(()=>{animation=null;resolve();},animation.duration));}
async function finishTurn(r){const b=r.battle;if(b.outcome){locked=false;if(b.outcome==='win')sound('victory');crowdNoise(null);if(training){training=null;go('shop');return;}E.settle(run,meta);save();go('result');return;}if(b.turn==='e'){locked=true;render();await new Promise(resolve=>setTimeout(resolve,250));E.act(b,E.ai(b),'e');if(!training)save();await animate(b);return finishTurn(r);}locked=false;render();}
function walkTown(x,y,done){townTravel={from:{...townPosition},to:{x,y},start:performance.now(),duration:650,done};locked=!!done;}
function draw(time){const dpr=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);if(shake>.4){const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduce)shake=0;else{ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.82;}}else shake=0;ctx.clearRect(-20,-20,w+40,h+40);const fight=view==='fight',im=fight?arenaBackdrop:town;if(im){if(fight){const s=Math.max(w/im.width,h/im.height);ctx.drawImage(im,(w-im.width*s)/2,(h-im.height*s)/2,im.width*s,im.height*s);}else if(view==='shop'){ctx.fillStyle='#132f29';ctx.fillRect(0,0,w,h);}else if(view==='town'&&w<800){const box=screen.querySelector('.town-scene')?.getBoundingClientRect();ctx.fillStyle='#283c2b';ctx.fillRect(0,0,w,h);if(box){const ih=w*im.height/im.width;ctx.drawImage(im,im.width*.3,im.height*.8,im.width*.4,im.height*.2,0,box.y+ih-1,w,Math.max(1,box.height-ih+1));ctx.drawImage(im,0,box.y,w,ih);}}else{const s=Math.max(w/im.width,h/im.height);ctx.drawImage(im,(w-im.width*s)/2,(h-im.height*s)/2,im.width*s,im.height*s);}}ctx.fillStyle=fight?'#071b1845':view==='town'?'#102c2410':'#102c2470';ctx.fillRect(0,0,w,h);
const paint=(kind,x,y,gear,scale,opts={})=>hero(ctx,art,kind,x,y,{...gear,magic:0},{scale,time:time/1000,marketGear:costume(market,kind,gear,view==='shop'&&shopSlot==='ranged'?'ranged':'melee'),...opts});
if(art){if(view==='choose'){['dwarf','ranger','mage'].forEach((k,i)=>paint(k,w*(.2+i*.3),h*.5,E.newRun(k).gear,Math.min(w/900,h/680)));}
else if(fight){const b=training?.battle||run.battle,{floor,map,scale:s}=arenaLayout(w,h,b),crowd=(b.crowd??E.CROWD_START)/100,seconds=time/1000;const shade=ctx.createLinearGradient(0,0,0,h*.65);shade.addColorStop(0,'#071714a8');shade.addColorStop(1,'transparent');ctx.fillStyle=shade;ctx.fillRect(0,0,w,h*.7);ctx.fillStyle='#8d714355';ctx.beginPath();ctx.ellipse(w/2,floor+28,w*.58,h*.15,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#47331fdd';ctx.fillRect(0,floor+31,w,h-floor);ctx.fillStyle='#c69b5f';ctx.fillRect(0,floor+31,w,7);for(let i=0;i<30;i++){const row=i%3,x=(i*83%997)/997*w,y=h*(.25+row*.06),bounce=Math.sin(seconds*(2+crowd*4)+i)*crowd*3;ctx.fillStyle=i%3?'#231b18cc':'#d0a85caa';ctx.beginPath();ctx.arc(x,y+bounce,2.5+crowd*1.5,0,Math.PI*2);ctx.fill();}for(const k of ['p','e']){const a=b[k],ev=animation?.events.find(v=>v.type==='action'&&v.who===k),hit=animation?.events.find(v=>v.type==='hit'&&v.target===k),t=animation?Math.min(1,(time-animation.start)/animation.duration):1,x=ev?ev.from+(ev.to-ev.from)*Math.min(1,t*1.2):a.x,jump=ev?.id==='jump'?Math.sin(t*Math.PI)*(76+a.stats.stride*12):0,recoil=hit?Math.sin(t*Math.PI)*18*(k==='p'?-1:1):0,y=floor-jump;paint(a.hero,map(x)+recoil,y,a.gear,s,{face:k==='p'?1:-1,moving:ev&&ev.from!==ev.to,walk:t*10,hurt:hit?1-t:0,attack:ev&&['quick','normal','heavy','shoot','charge','shove'].includes(ev.id)?{t,duration:1}:null});if(a.guard||a.shield){ctx.strokeStyle=a.shield?'#a4deff':'#ffe49f';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(map(x),floor-82*s,62*s,102*s,0,0,Math.PI*2);ctx.stroke();}if(ev&&ev.from!==ev.to&&t>.72){ctx.globalAlpha=Math.max(0,1-t);ctx.fillStyle='#ead5a0';for(let n=0;n<5;n++){ctx.beginPath();ctx.arc(map(x)+(n-2)*8,floor+4-n%2*5,3+n%2*2,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}}
if(animation){const ev=animation.events[0],t=Math.min(1,(time-animation.start)/animation.duration),target=ev.who==='p'?'e':'p';if(['lightning','frost','meteor','sleep','shoot'].includes(ev.id)){ctx.strokeStyle=ev.id==='lightning'?'#fff2a0':ev.id==='sleep'?'#d4acff':'#9ce5ff';ctx.lineWidth=ev.id==='meteor'?12:4;ctx.beginPath();ctx.moveTo(map(b[ev.who].x),floor-100*s);ctx.lineTo(map(b[ev.who].x)+(map(b[target].x)-map(b[ev.who].x))*t,floor-95*s);ctx.stroke();}for(const miss of animation.events.filter(e=>e.type==='miss')){ctx.textAlign='center';ctx.fillStyle='#e9f4ef';ctx.font='900 28px Nunito';ctx.fillText('MISS',map(b[miss.target].x),floor-230*s-t*28);}for(const hit of animation.events.filter(e=>e.type==='hit')){const hx=map(b[hit.target].x),hy=floor-220*s-t*25;ctx.textAlign='center';if(hit.crit){ctx.fillStyle='#fff3c4';ctx.font='bold 15px Nunito';ctx.fillText('CRITICAL!',hx,hy-30);ctx.fillStyle='#ff9d5c';ctx.font='bold 40px Nunito';}else{ctx.fillStyle=hit.blocked||hit.absorbed?'#9fe4ff':'#ffe4aa';ctx.font='bold 28px Nunito';if(hit.blocked||hit.absorbed)ctx.fillText(hit.absorbed?'AEGIS':'BLOCK',hx,hy-28);}ctx.fillText('-'+hit.damage,hx,hy);}
for(const cry of animation.events.filter(e=>e.type==='taunt')){ctx.fillStyle='#ffd972';ctx.font='bold 30px Nunito';ctx.textAlign='center';ctx.globalAlpha=1-t*.45;ctx.fillText('!',map(b[cry.who].x)-14+t*6,floor-210*s-t*18);ctx.fillText('!',map(b[cry.who].x)+16-t*6,floor-224*s-t*24);ctx.globalAlpha=1;}}}
else if(view==='town'){const seconds=time/1000,townBox=w<800?screen.querySelector('.town-scene')?.getBoundingClientRect():null,ty=townBox?.y||0,th=townBox?.height||h,sceneH=townBox?w*2/3:h;for(const [cat,x] of [['weapons',.15],['magic',.69],['armor',.92]])drawKeeper(ctx,market,cat,w*x,ty+sceneH*.76,Math.min(w*.19,sceneH*.3),seconds);for(let i=0;i<16;i++){const phase=(seconds*.35+i*.13)%1;ctx.globalAlpha=(1-phase)*.7;ctx.fillStyle=i%2?'#ffa94b':'#a7f4ee';const x=i%2?.14:.685;ctx.beginPath();ctx.arc(w*x+Math.sin(i*9+seconds)*w*.014,ty+sceneH*(.5-phase*.15),1.5+phase*2,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;if(townTravel){const t=Math.min(1,(time-townTravel.start)/townTravel.duration);townPosition={x:townTravel.from.x+(townTravel.to.x-townTravel.from.x)*t,y:townTravel.from.y+(townTravel.to.y-townTravel.from.y)*t};if(t===1){const done=townTravel.done;townTravel=null;locked=false;done?.();}}paint(run.hero,w*townPosition.x,ty+th*townPosition.y,run.gear,Math.min(w/790,th/590,w>=800?.95:.82),{moving:!!townTravel,walk:seconds*10,face:townTravel&&townTravel.to.x<townTravel.from.x?-1:1});}
else if(view==='shop'){const box=screen.querySelector('.market-stage')?.getBoundingClientRect();if(box){const bg=market.interiors,idx=KEEPERS[category].index;const sw=bg.width/3,ratio=Math.max(box.width/sw,box.height/bg.height),sh=box.height/ratio,cw=box.width/ratio;ctx.drawImage(bg,idx*sw+(sw-cw)/2,(bg.height-sh)*.72,cw,sh,box.x,box.y,box.width,box.height);if(category!=='armor'){const glow=ctx.createRadialGradient(box.x+box.width*.5,box.y+box.height*.25,0,box.x+box.width*.5,box.y+box.height*.25,box.width*.4);glow.addColorStop(0,category==='magic'?'#78efff':'#ffb74d');glow.addColorStop(1,'transparent');ctx.globalAlpha=.1+Math.sin(time/300)*.035;ctx.fillStyle=glow;ctx.fillRect(box.x,box.y,box.width,box.height);ctx.globalAlpha=1;}const scale=Math.min((box.height-44)/260,box.width/450,w>=800?1.08:.9),floor=box.bottom-36;drawKeeper(ctx,market,category,box.x+box.width*.2,floor,scale*220,time/1000);paint(run.hero,box.x+box.width*.57,floor,previewRun().gear,scale,{fitting:true});if(category==='magic'&&preview){const spell=itemSprite(market,run.hero,'magic',preview),sz=scale*68;ctx.drawImage(spell,box.x+box.width*.8-25,floor-160*scale,sz,sz);}}}
else if(view==='offer'||view==='tournament'){const o=run.tournament?E.tournamentOffer(run):run.offer,box=screen.querySelector('.rival-portrait-space')?.getBoundingClientRect();if(box){const s=box.height/270;paint(run.hero,w*.38,box.bottom,run.gear,s);paint(o.hero,w*.62,box.bottom,o.gear,s,{face:-1});}}
}requestAnimationFrame(draw);}
try{[art,town,arenaBackdrop,market]=await Promise.all([assets(),(async()=>{const i=new Image();i.src='assets/crownlands/town.webp';await i.decode();return i;})(),(async()=>{const i=new Image();i.src='assets/art/ember-arena.webp';await i.decode();return i;})(),loadMarket()]);$('loading').remove();view=run?.battle?'fight':run?.result?'result':run?.tournament?'tournament':run?'town':'choose';render();requestAnimationFrame(draw);if(run?.battle){locked=true;await finishTurn(run);}}catch(e){$('loading').textContent='Unable to load the arena. Please refresh to try again.';console.error(e);}
